# ---------------------------------------------------------------- loop H: shift leaves '.', or --fill KEY

FLOOR = "k #000000\nf #806040\nffff\nfkkf\nfkkf\nffff\n"


def test_shift_vacated_pixels_become_dot(tmp_path):
    p = write(tmp_path, "a.px", "k #000000\nkk..\nkk..\n")
    assert run("shift", p, "--dx", "2") == 0
