def test_negative_coordinates_are_not_options(tmp_path):
    p = canvas(tmp_path, 3, 3)
    assert run("line", f"{p}:a", "k", "-1,-1", "1,1") == 0
    assert run("rect", f"{p}:a", "w", "-1,-1,2,2", "--fill") == 0
    assert run("ellipse", f"{p}:a", "k", "-1,-1,1,1") == 0
