    p = write(tmp_path, "r.px", "k #000000\nj #ffffff\n@frame a pivot=2,0\nkkj\nk..\n")
    for cmd in (["rotate", "90"], ["rotate", "270"], ["transpose"], ["rotate", "180"]):
        assert run(cmd[0], f"{p}:a", *cmd[1:]) == 0
        doc = pxart.parse(p)
        x, y = doc.get("a").pivot
        assert doc.get("a").grid[y][x] == "j"


