    for x, y in ring:
        assert (x, y) not in shape
        for dx, dy in pxart.CORNERS:  # an L: two ring side-neighbors that touch each other at a corner
            assert not ((x + dx, y) in ring and (x, y + dy) in ring and (x + dx, y + dy) not in shape), (x, y)


