    assert run("outline", f"{q}:a", "--key", "o", "--lit", "l") == 0
    assert run("render", f"{q}:a", "-o", tmp_path / "r.png") == 0
    assert list(pxart.pixels(Image.open(tmp_path / "v.png").convert("RGBA"))) == \
        list(pxart.pixels(Image.open(tmp_path / "r.png").convert("RGBA")))


