    dx, dy, n_shift, n_none, still = motion_of(tmp_path, IDLE_4[0], IDLE_4[1])
    assert still == 9
    dx, dy, n_shift, n_none, still = motion_of(tmp_path, IDLE_4[1], IDLE_4[0])
