    assert run("palette", hero, "--hoist", "l") == 0
    doc = pxart.parse(hero)
    assert list(doc.palette) == ["g"] and doc.variants == {"night": {"g": (0xff, 0xc8, 0x61, 255)}}
    assert "l #fff4b0" in pal.read_text() and looks(doc) == before


