def test_scene_map_overhang_gets_one_note(tmp_path, capsys):
    write(tmp_path, "t.px", "k #000000\n\n" + ("k" * 4 + "\n") * 4)
    write(tmp_path, "tall.px", "k #000000\n\n" + ("k" * 4 + "\n") * 8)
