def test_from_png_palette_missing_says_the_base(tmp_path, monkeypatch):
    t = paths_tree(tmp_path)
    monkeypatch.chdir(t)
    Image.new("RGBA", (1, 1), (1, 2, 3, 255)).save(t / "i.png")
    msg = run_err("from-png", "i.png", "--palette", "nope.px", "-o", "game/i.px")
